<?php use VO\Support\Template; use VO\Cart\CartController; ob_start(); ?>
<p><a href="/">← Ver catálogo</a></p><h1>Tu carrito</h1><?php if ($flash): ?><p class="notice"><?= Template::e($flash) ?></p><?php endif; ?>
<?php if (!$state['details']): ?><section class="card"><p>Tu carrito está vacío.</p><a class="button" href="/">Ver catálogo</a></section><?php else: ?>
<section class="cart-list"><?php foreach ($state['details'] as $line): ?><article class="card cart-row" data-cart-item-id="<?= (int)$line['id'] ?>"><h2><?= Template::e($line['name']) ?></h2><?php if ($line['unavailable']): ?><p class="warning">Este ítem ya no está disponible. Quitalo para continuar.</p><?php endif; ?><p>Cantidad: <?= (int)$line['qty'] ?></p><p><?= Template::e(CartController::money((int)($line['pricing']['line_total_cents'] ?? 0))) ?></p><form method="post" action="/carrito"><input type="hidden" name="action" value="update"><input type="hidden" name="cart_item_id" value="<?= (int)$line['id'] ?>"><button type="button" data-cart-qty="minus">−</button><input name="qty" type="number" min="1" value="<?= (int)$line['qty'] ?>"><button type="button" data-cart-qty="plus">+</button><button>Actualizar</button></form><form method="post" action="/carrito"><input type="hidden" name="action" value="remove"><input type="hidden" name="cart_item_id" value="<?= (int)$line['id'] ?>"><button data-cart-remove>Quitar</button></form></article><?php endforeach; ?></section>
<form class="card" data-cart-coupon><label>Cupón <input name="coupon_code" value="<?= Template::e($state['cart']['coupon_code'] ?? '') ?>"></label><button>Aplicar cupón</button></form><p class="total">Total: <?= Template::e(CartController::money((int)$state['pricing']['grand_total_cents'])) ?></p><p><a class="button" href="/checkout">Ir a checkout</a></p><?php endif; ?>
<script src="/assets/js/shop/cart.js" defer></script><?php $content = ob_get_clean(); require dirname(__DIR__, 2) . '/Catalog/templates/layout.php'; ?>
